package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.logistics.itemHatch.*;
import java.util.*;
import net.fabricmc.fabric.api.entity.FakePlayer;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.Registries;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.world.*;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.EntityTypes;
import net.minecraft.world.inventory.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.ItemContainerContents;
import net.minecraft.world.item.enchantment.Enchantments;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.phys.*;

/** Native finite-owner and vanilla attack/anvil boundaries. Proposed GameTests, runtime UNRUN. */
public final class HatchSwordGameTests {
 private static final BlockPos P=new BlockPos(3,3,3);
 private static BlockPos hatch(GameTestHelper h){var p=h.absolutePos(P);h.getLevel().setBlockAndUpdate(p.north(),Blocks.CHEST.defaultBlockState());h.getLevel().setBlockAndUpdate(p,AllBlocks.ITEM_HATCH.defaultBlockState().setValue(ItemHatchBlock.FACING,Direction.NORTH));return p;}
 private static ChestBlockEntity chest(GameTestHelper h,BlockPos p){return (ChestBlockEntity)h.getLevel().getBlockEntity(p.north());}
 private static NativeSurvivalTestPlayer player(GameTestHelper h,BlockPos p){return NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(p).add(0,0,2));}
 private static InteractionResult use(net.minecraft.server.level.ServerPlayer player,BlockPos p){return player.gameMode.useItemOn(player,player.level(),player.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atLowerCornerOf(p).add(.5,.95,.95),Direction.SOUTH,p,false));}
 private static ItemStack named(Item item,int count){var stack=new ItemStack(item,count);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original hatch stock"));return stack;}
 private static ItemStack cargo(){var stack=named(Items.BARREL,1);stack.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(named(Items.EMERALD,7))));return stack;}
 private static int count(Container owner,Item item){int n=0;for(int i=0;i<owner.getContainerSize();i++)if(owner.getItem(i).is(item))n+=owner.getItem(i).getCount();return n;}

 @GameTest public void normalNativeUseMovesOnlySelectedOriginalCargoOwner(GameTestHelper h){var p=hatch(h);try(var joined=player(h,p)){var player=joined.player();player.getInventory().setSelectedSlot(2);var original=cargo();player.getInventory().setItem(2,original);player.getInventory().setItem(0,new ItemStack(Items.APPLE,4));player.getInventory().setItem(9,new ItemStack(Items.DIRT,6));player.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.GOLD_INGOT,3));h.assertTrue(use(player,p).consumesAction()&&original.isEmpty(),"Actual native use transfers the sole selected survival stack");h.assertTrue(ItemStack.matches(chest(h,p).getItem(0),cargo())&&player.getInventory().getItem(0).getCount()==4&&player.getInventory().getItem(9).getCount()==6&&player.getOffhandItem().getCount()==3,"Full original component/cargo variant reaches the actual chest once; other hotbar, main and offhand owners remain");}h.succeed();}
 @GameTest public void secondaryNativeUseMovesMainInventoryAndExcludesEveryHotbarAndOffhandSlot(GameTestHelper h){var p=hatch(h);try(var joined=player(h,p)){var player=joined.player();for(int i=0;i<9;i++)player.getInventory().setItem(i,new ItemStack(Items.APPLE,i+1));player.getInventory().setItem(9,named(Items.DIRT,5));player.getInventory().setItem(35,named(Items.IRON_INGOT,7));player.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.DIAMOND,3));player.setShiftKeyDown(true);h.assertTrue(use(player,p).consumesAction(),"Actual native secondary-use callback reaches original hatch interaction");for(int i=0;i<9;i++)h.assertValueEqual(player.getInventory().getItem(i).getCount(),i+1,"Source excludes hotbar slot "+i);h.assertTrue(player.getInventory().getItem(9).isEmpty()&&player.getInventory().getItem(35).isEmpty()&&player.getOffhandItem().getCount()==3&&count(chest(h,p),Items.DIRT)==5&&count(chest(h,p),Items.IRON_INGOT)==7,"Only real main inventory slots9 through35 transfer to finite adjacent storage");}h.succeed();}
 @GameTest public void partialNativeChestCapacityRetainsExactUnacceptedOriginalRemainder(GameTestHelper h){var p=hatch(h);var chest=chest(h,p);for(int i=0;i<26;i++)chest.setItem(i,new ItemStack(Items.STONE,64));chest.setItem(26,named(Items.APPLE,62));try(var joined=player(h,p)){var player=joined.player();var original=named(Items.APPLE,5);player.setItemInHand(InteractionHand.MAIN_HAND,original);use(player,p);h.assertTrue(ItemStack.matches(player.getMainHandItem(),named(Items.APPLE,3))&&ItemStack.matches(chest.getItem(26),named(Items.APPLE,64))&&count(chest,Items.STONE)==26*64,"One actual shared transaction moves exactly two matching named items; three original items remain owned by the player");use(player,p);h.assertTrue(ItemStack.matches(player.getMainHandItem(),named(Items.APPLE,3))&&count(chest,Items.APPLE)==64,"A full native destination cannot consume, re-create or clean the original remainder");}h.succeed();}
 @GameTest public void realFilterPredicateAndPaidFilterOwnershipSurviveNativeSaveAndDrop(GameTestHelper h){var p=hatch(h);var hatch=(ItemHatchBlockEntity)h.getLevel().getBlockEntity(p);try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.APPLE,2));hatch.filtering.applyPlayerSample(player,InteractionHand.MAIN_HAND);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIRT,4));use(player,p);h.assertTrue(player.getMainHandItem().getCount()==4&&count(chest(h,p),Items.DIRT)==0,"Original plain sample rejects unrelated real stock");player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.APPLE,3));use(player,p);h.assertTrue(player.getMainHandItem().isEmpty()&&count(chest(h,p),Items.APPLE)==3,"Original source filter accepts actual matching stock");var paid=named(AllItems.FILTER,2);player.setItemInHand(InteractionHand.MAIN_HAND,paid);hatch.filtering.applyPlayerSample(player,InteractionHand.MAIN_HAND);h.assertValueEqual(paid.getCount(),1,"An actual source filter item pays one owned sample");var detached=BlockEntity.loadStatic(p,hatch.getBlockState(),hatch.saveWithFullMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(detached instanceof ItemHatchBlockEntity saved&&saved.getLevel()==null&&ItemStack.matches(saved.filtering.getFilter(),named(AllItems.FILTER,1)),"Native save codec preserves one detached exact paid filter without another world owner");h.getLevel().destroyBlock(p,true);var drops=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(p).inflate(1.5));h.assertTrue(drops.stream().filter(e->e.getItem().is(AllItems.FILTER)).mapToInt(e->e.getItem().getCount()).sum()==1&&hatch.filtering.getFilter().isEmpty(),"Actual native removal transfers the sole paid filter receipt once");}h.succeed();}
 @GameTest(maxTicks=30) public void actualHatchEngineTickClosesAfterTenTicks(GameTestHelper h){var p=hatch(h);try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.APPLE,2));use(player,p);h.assertTrue(h.getLevel().getBlockState(p).getValue(ItemHatchBlock.OPEN),"Accepted original deposit sets genuine native OPEN state");}h.runAfterDelay(9,()->h.assertTrue(h.getLevel().getBlockState(p).getValue(ItemHatchBlock.OPEN),"Actual source hatch remains open before ten ticks"));h.runAfterDelay(11,()->{h.assertFalse(h.getLevel().getBlockState(p).getValue(ItemHatchBlock.OPEN),"Actual scheduled native block tick closes the source hatch");h.succeed();});}
 @GameTest public void actualFakePlayerAndAdventureAbilitiesCannotDepositOriginalStock(GameTestHelper h){var p=hatch(h);var state=h.getLevel().getBlockState(p);var fake=FakePlayer.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"hatch_fixture"));var original=new ItemStack(Items.APPLE,4);fake.setItemInHand(InteractionHand.MAIN_HAND,original);AllBlocks.ITEM_HATCH.deposit(original,state,h.getLevel(),p,fake);h.assertTrue(fake.getMainHandItem()==original&&original.getCount()==4&&chest(h,p).isEmpty(),"Real Fabric FakePlayer receives source success without moving original stock");try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIRT,3));player.setGameMode(net.minecraft.world.level.GameType.ADVENTURE);use(player,p);h.assertTrue(player.getMainHandItem().getCount()==3&&chest(h,p).isEmpty(),"Native adventure mayBuild guard rejects actual hatch transfer");}h.succeed();}
 @GameTest public void sourceShapeAndActualSneakWrenchRotateOrRemoveGenuineHatch(GameTestHelper h){var p=hatch(h);h.assertValueEqual(h.getLevel().getBlockState(p).getShape(h.getLevel(),p).bounds(),new AABB(1/16d,0,0,15/16d,1,7.8/16d),"Pinned NORTH native hatch collision extent");try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));var hit=new BlockHitResult(Vec3.atCenterOf(p),Direction.UP,p,false);AllItems.WRENCH.useOn(new net.minecraft.world.item.context.UseOnContext(player,InteractionHand.MAIN_HAND,hit));h.assertTrue(h.getLevel().getBlockState(p).getValue(ItemHatchBlock.FACING)==Direction.EAST,"Actual source wrench rotates hatch through native shared path");player.setShiftKeyDown(true);use(player,p);h.assertTrue(h.getLevel().getBlockState(p).isAir()&&player.getInventory().countItem(AllBlocks.ITEM_HATCH.asItem())==1,"Native secondary wrench reaches removal and returns one genuine wrapper instead of depositing wrench");}h.succeed();}
 @GameTest public void originalSwordUsesModernNativeWeaponComponentsWithZeroSourceWear(GameTestHelper h){var sword=new ItemStack(AllItems.CARDBOARD_SWORD);h.assertTrue(sword.getMaxStackSize()==1&&!sword.isDamageableItem()&&!sword.has(DataComponents.MAX_DAMAGE)&&!sword.has(DataComponents.DAMAGE)&&sword.has(DataComponents.WEAPON)&&sword.has(DataComponents.TOOL)&&sword.has(DataComponents.ATTRIBUTE_MODIFIERS)&&sword.has(DataComponents.ENCHANTABLE)&&sword.has(DataComponents.REPAIRABLE)&&sword.has(DataComponents.COOKING_FUEL),"Genuine native sword/attributes/enchant/repair/fuel components preserve source zero wear without an invalid max_damage0 codec");h.succeed();}
 @GameTest public void actualPlayerAttackCannotHurtCreatureAndDismountsSlowsAndKnocksBack(GameTestHelper h){var p=h.absolutePos(P);var cow=h.spawnWithNoFreeWill(EntityTypes.COW,3.5f,3,3.5f);var mount=h.spawnWithNoFreeWill(EntityTypes.PIG,3.5f,3,3.5f);h.assertTrue(cow.startRiding(mount,true,false),"Original real creature rides a genuine native mount");float health=cow.getHealth();try(var joined=player(h,p)){var player=joined.player();var sword=named(AllItems.CARDBOARD_SWORD,1);player.setItemInHand(InteractionHand.MAIN_HAND,sword);player.setYRot(0);player.setDeltaMovement(1,.2,1);player.setSprinting(true);player.attack(cow);var slow=cow.getEffect(MobEffects.SLOWNESS);h.assertTrue(cow.getHealth()==health&&!cow.isPassenger()&&slow!=null&&slow.getDuration()==60&&slow.getAmplifier()==9&&cow.getDeltaMovement().horizontalDistanceSqr()>0,"Real Player.attack mixin cancels damage and applies source dismount, native knockback and sixty-tick creature slowness");h.assertTrue(player.getMainHandItem()==sword&&ItemStack.matches(sword,named(AllItems.CARDBOARD_SWORD,1))&&!player.isSprinting()&&Math.abs(player.getDeltaMovement().x-.6)<.0001&&Math.abs(player.getDeltaMovement().z-.6)<.0001,"Original sword and all named components remain; actual source attacker motion is multiplied by0.6");}h.succeed();}
 @GameTest public void actualArthropodAttackFollowsVanillaDamagePath(GameTestHelper h){var spider=h.spawnWithNoFreeWill(EntityTypes.SPIDER,3.5f,3,3.5f);float health=spider.getHealth();try(var joined=player(h,h.absolutePos(P))){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,named(AllItems.CARDBOARD_SWORD,1));player.attack(spider);h.assertTrue(spider.getHealth()<health&&!spider.hasEffect(MobEffects.SLOWNESS)&&ItemStack.matches(player.getMainHandItem(),named(AllItems.CARDBOARD_SWORD,1)),"Actual source ARTHROPOD exception retains native damage without creature slowness or zero-wear sword loss");}h.succeed();}
 @GameTest public void realNativeAnvilRejectsEntireMixedBookAndRetainsBothInputOwners(GameTestHelper h){var p=h.absolutePos(P);try(var joined=player(h,p)){var player=joined.player();var enchantments=h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT);var sword=named(AllItems.CARDBOARD_SWORD,1);var book=new ItemStack(Items.ENCHANTED_BOOK);book.enchant(enchantments.getOrThrow(Enchantments.KNOCKBACK),1);book.enchant(enchantments.getOrThrow(Enchantments.SHARPNESS),1);var menu=new AnvilMenu(7,player.getInventory(),ContainerLevelAccess.create(h.getLevel(),p));menu.getSlot(0).set(sword);menu.getSlot(1).set(book);menu.createResult();h.assertTrue(menu.getSlot(2).getItem().isEmpty()&&menu.getCost()==0&&menu.getSlot(0).getItem()==sword&&menu.getSlot(1).getItem()==book&&book.get(DataComponents.STORED_ENCHANTMENTS).size()==2,"Actual AnvilMenu production mixin refuses complete unsupported mixed book, preserving each finite original input");var accepted=new ItemStack(Items.ENCHANTED_BOOK);accepted.enchant(enchantments.getOrThrow(Enchantments.KNOCKBACK),1);menu.getSlot(1).set(accepted);menu.createResult();h.assertTrue(!menu.getSlot(2).getItem().isEmpty()&&menu.getSlot(2).getItem().getEnchantments().getLevel(enchantments.getOrThrow(Enchantments.KNOCKBACK))==1&&menu.getSlot(0).getItem()==sword&&menu.getSlot(1).getItem()==accepted,"Actual native enchantment event/anvil path accepts Knockback-only original book without consuming inputs during preview");menu.getSlot(0).set(ItemStack.EMPTY);menu.getSlot(1).set(ItemStack.EMPTY);menu.removed(player);}h.succeed();}
}
